class SmsRequestHandler {
  constructor(private repo: SmsRepo, private scheduler: SmsScheduler) {}

  async submit(input: { phone: string; text: string; sendAt?: number }) {
    if (!input.phone || !input.text) throw new Error('phone and text are required');
    const task = await this.repo.create({
      phone: input.phone,
      text: input.text,
      status: 'pending',
      attempts: 0
    });
    await this.scheduler.schedule({ taskId: task.id }, input.sendAt);
    return { taskId: task.id };
  }
}

class SmsWorker {
  constructor(
    private repo: SmsRepo,
    private scheduler: SmsScheduler,
    private gateway: SmsGateway
  ) {}

  async handle(job: { taskId: string }) {
    const task = await this.repo.get(job.taskId);
    await this.repo.setStatus(task.id, 'sending');
    const result = await this.gateway.send(task.phone, task.text);

    if (result.retryable && task.attempts < 2) {
      const attempts = task.attempts + 1;
      await this.repo.setAttempts(task.id, attempts);
      await this.repo.setStatus(task.id, 'retry_wait');
      await this.scheduler.schedule({ taskId: task.id }, Date.now() + attempts * 5000);
      return;
    }

    await this.repo.setGatewayId(task.id, result.messageId);
    await this.repo.setStatus(task.id, result.accepted ? 'sent' : 'failed');
  }
}

class GatewayReceiptController {
  constructor(private receipts: SmsReceiptHandler) {}

  async receive(receipt: { taskId: string; messageId: string; delivered: boolean }) {
    await this.receipts.handle(receipt);
    return { accepted: true };
  }
}

class SmsReceiptHandler {
  constructor(private repo: SmsRepo, private events: EventBus) {}

  async handle(receipt: { taskId: string; messageId: string; delivered: boolean }) {
    const task = await this.repo.get(receipt.taskId);
    if (!task || task.gatewayId !== receipt.messageId) return;
    const status = receipt.delivered ? 'delivered' : 'undelivered';
    await this.repo.setStatus(task.id, status);
    await this.events.publish({ type: 'sms.status', taskId: task.id, status });
  }
}
